	@Test
	void coreComputesInitials() throws Exception {
		ObjectNode o = ownerNode();
		o.put("firstName", "john"); o.put("lastName", "smith");
		int id = createOwnerOk(o);
		getOwner(id).andExpect(jsonPath("$.initials").value("J.S."));
	}
}

